class StaticParent { static String label(){ return "parent"; } }
class StaticChild extends StaticParent { static String label(){ return "child"; } }
public class StaticHidingDemo {
    public static void main(String[] args){
        StaticParent ref = new StaticChild();
        System.out.println(ref.label());
        System.out.println(StaticChild.label());
    }
}
